INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('13d466b4-7a2d-4067-b17f-f9d65cc2dfc0', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$31. óra: A törtek szorzását alkalmazó feladatok megoldása$q$, $q$Törtrész kiszámítása és szöveges feladatok megoldása szorzással.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Törtek$q$, $q$[{"id": "834d6637-4998-4f68-8cf9-20b8d4f806f8", "text": "Mennyi 60-nak a 3/4 része? (60 * 3/4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "45"}, {"id": "d160ed55-aa1c-4282-976c-9a8fefca2cde", "text": "Mennyi 100-nak az 1/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "48832122-98ac-431e-a7a5-58a2c8a7fc75", "text": "Egy 24 szeletes tortának megették az 1/3-át. Hány szeletet ettek meg?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "5e43084f-0ff0-44b4-8dae-0d893fd277af", "text": "Egy 24 szeletes tortának megették az 1/3-át. Hány szelet maradt?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "16"}, {"id": "4201d1e6-e0eb-4975-9265-7decbdf32002", "text": "Egy szám törtrészének kiszámításához a számot megszorozzuk a törttel.", "type": "true-false", "options": [{"id": "704ebf04-f5e9-4fd3-bb6d-7aa2ad02ffa3", "text": "Igaz", "isCorrect": true}, {"id": "8446f3c1-19f7-4f63-8ddb-ba5729c74630", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5f2afb34-000b-40d9-9a85-1115871d8daa", "text": "Mennyi 50-nek a 2/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "7cb212e4-aaa5-40fe-b0ff-d6682fb11059", "text": "Mennyi 1/2 óra percekben? (60 * 1/2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b70e2a67-bfda-4f0f-a28f-8acf46c1e3d3', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$32. óra: Osztás törttel$q$, $q$Törttel való osztás szabálya: szorzás a reciprokával.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Törtek$q$, $q$[{"id": "b8c567bb-0308-4738-9d26-708987857f10", "text": "Hogyan osztunk törttel?", "type": "multiple-choice", "options": [{"id": "2705127e-883d-46ab-99b9-bc9d126faf96", "text": "Az osztandót megszorozzuk az osztó reciprokával", "isCorrect": true}, {"id": "ccbe57a7-89bf-4b60-9464-8a62047c9c4c", "text": "Az osztandót elosztjuk a nevezővel", "isCorrect": false}, {"id": "6c075478-0f23-4bab-a077-a6e567f65c3c", "text": "Mindig 1-et kapunk", "isCorrect": false}, {"id": "a5eb9341-4a08-49b5-b6da-99dd713c6c14", "text": "A számlálókat elosztjuk egymással", "isCorrect": false}], "timeLimit": 15}, {"id": "85912786-0d5e-4c3f-8a60-1e659c9fd9fc", "text": "Mennyi 2/3 : 4/5? (2/3 * 5/4)", "type": "multiple-choice", "options": [{"id": "c7f8325a-5fba-4bf7-8d3c-056d65c6d4f2", "text": "10/12 (azaz 5/6)", "isCorrect": true}, {"id": "c9fab617-390d-45d1-ad9e-c1edab26821d", "text": "8/15", "isCorrect": false}, {"id": "cd13bba3-a03d-4c44-820c-92461d15bee2", "text": "6/8", "isCorrect": false}, {"id": "9c6165ce-4707-4e03-9631-9ff16a61a012", "text": "15/8", "isCorrect": false}], "timeLimit": 15}, {"id": "8520c009-8440-456d-968c-19eec287be89", "text": "Mennyi 1/2 : 1/2?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "1423d672-c985-4fa8-8e46-6e429e081750", "text": "Ha egy számot 1/2-del osztunk, az eredmény megegyezik a szám 2-vel való szorzatával.", "type": "true-false", "options": [{"id": "03f4a1fc-e3fa-42eb-804f-cb93a10d32e4", "text": "Igaz ( : 1/2 = * 2)", "isCorrect": true}, {"id": "ed152898-450e-4439-ba38-23acc0ebe640", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "0b06c92b-dce1-4146-a579-85f82f9e6d07", "text": "Mennyi 6 : 1/3? (6 * 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}, {"id": "b36c07eb-1ed7-49e4-a3b0-b416a23f7643", "text": "Törttel való osztáskor az osztandó nem változik, csak az osztót fordítjuk meg.", "type": "true-false", "options": [{"id": "77bb489b-f02f-417a-9078-7d04bf0a90ab", "text": "Igaz", "isCorrect": true}, {"id": "1947aa7b-065b-4ff6-8188-141a0454811f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e0e557cd-3ad3-43d8-902c-e967aaa09d54", "text": "Mennyi 3/4 : 3/4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('bb535479-8317-4927-bdef-70b1bc67e7be', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$33. óra: Hétköznapi problémák megoldása törtek osztásának felhasználásával$q$, $q$Szöveges feladatok mérésekkel, átdarabolásokkal, törtek osztásával.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Törtek$q$, $q$[{"id": "82de320b-0b29-4ccd-98d6-b96622a5a748", "text": "Hány 1/4 literes pohár tölthető meg 3 liter almaléből? (3 : 1/4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "6e1bed3d-c760-4ef4-b435-e609cd2d070e", "text": "Hány 1/2 kg-os csomag képezhető 5 kg cukorból?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "af19bb95-fc43-49a9-b0bc-644f7fb01893", "text": "Egy 6 méteres szalagból 3/4 méteres darabokat vágunk. Hány darabot kapunk? (6 : 3/4 = 6 * 4/3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "cd053583-8c51-43bc-aabe-c9dde12cabb2", "text": "Törtek osztásakor az eredmény lehet nagyobb az eredeti osztandónál, ha az osztó 1-nél kisebb tört.", "type": "true-false", "options": [{"id": "539b4abf-963c-49c5-ba31-4cecde45c12d", "text": "Igaz", "isCorrect": true}, {"id": "5bcae6c0-7dac-4315-acce-ac1e3e328f6f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "07856c4f-77c7-4e11-abe8-f96736b42886", "text": "Hány 1/5 méteres darab vágható ki 2 méter anyagból?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "99592595-4376-4d34-b753-604b9757182c", "text": "A szöveges feladatoknál az adatok lejegyzése és a mértékegységek egyeztetése elengedhetetlen.", "type": "true-false", "options": [{"id": "399744e9-50cd-477b-9427-5a1b99d8eed0", "text": "Igaz", "isCorrect": true}, {"id": "6cc75a62-4f54-4f50-8611-73073345ade9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "11bb6561-c932-460b-9da3-6e1120c813b9", "text": "Mennyi 4 : 2/3? (4 * 3/2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('6298b6a3-b077-48fd-adfa-0c92613ed312', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$34. óra: Gyakorlóóra$q$, $q$A törtek szorzásának és osztásának rögzítése, feladatok gyakorlása.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Törtek$q$, $q$[{"id": "9be3a754-0ad0-4475-a4a8-53e943510fd0", "text": "Mennyi 3/5 * 5/3?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "7305f1fc-fbf2-4ed8-a693-d3f3613da0e2", "text": "Mennyi 4/7 : 2/7? (4/7 * 7/2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "c3ae557a-32ea-4e06-8474-46a1caa079ff", "text": "Melyik állítás igaz?", "type": "multiple-choice", "options": [{"id": "7a8a7067-b701-4b14-929c-d57e9be3bb34", "text": "Két 1-nél kisebb pozitív tört szorzata kisebb mindkét tényezőnél", "isCorrect": true}, {"id": "245590eb-95cb-4c18-95a2-cbee2d8e075e", "text": "A szorzat mindig nagyobb a tényezőknél", "isCorrect": false}, {"id": "ea14c44c-4417-4b1f-83fe-845636c3ee65", "text": "Az osztás mindig kisebb számot ad", "isCorrect": false}, {"id": "a3985b67-0e8a-475b-88ee-6963df6ab4de", "text": "Nincs reciproka a 4/5-nek", "isCorrect": false}], "timeLimit": 15}, {"id": "e2a5468e-a5f7-47a0-b471-5f4170dfa8f3", "text": "Mennyi 5/6 * 12? (5 * 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "aeb83f5d-9655-4fe5-bcb9-4765184635f4", "text": "A 2/3 osztva 1/3-dal 2-t ad.", "type": "true-false", "options": [{"id": "8debbdba-85d1-4932-a62d-559450c30e69", "text": "Igaz", "isCorrect": true}, {"id": "1a964124-e8f3-4f9e-b2f8-a0730b400364", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4740134d-b8bf-40b8-91eb-f91516225393", "text": "Mennyi 3/8 : 3/8?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "267f652f-ff99-453f-aeba-d50c4d415b20", "text": "Mennyi 1/4 * 4/5?", "type": "multiple-choice", "options": [{"id": "e0dab714-92a6-4f84-a157-864933fb17d2", "text": "1/5", "isCorrect": true}, {"id": "e10e001e-5041-41ab-a14c-0f12e2cec532", "text": "4/20", "isCorrect": false}, {"id": "8172b2d8-abbe-44da-8c8a-665a9958bfb1", "text": "1/20", "isCorrect": false}, {"id": "a5528d18-701c-40b5-9b0b-ec3fc3842e8b", "text": "4/9", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('9b61c79d-834a-4537-94fc-729e2aa191a1', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$35. óra: Számonkérés$q$, $q$Számonkérés a közönséges törtek műveleteiből (10 kérdés).$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Törtek$q$, $q$[{"id": "690611ff-fb91-4b25-88af-0584960b6d31", "text": "1. Mennyi 2/5 + 1/5?", "type": "multiple-choice", "options": [{"id": "a98cb8b2-9c8c-473e-8a66-8291630fbef1", "text": "3/5", "isCorrect": true}, {"id": "feb4e91b-d12c-4039-89a8-6658006c7ef7", "text": "3/10", "isCorrect": false}, {"id": "8a47d398-363a-498b-8c39-bff9ccfdd27f", "text": "2/10", "isCorrect": false}, {"id": "34edf3fb-9808-495e-b4f5-fa90afb05ae0", "text": "1/5", "isCorrect": false}], "timeLimit": 15}, {"id": "bb4f7c73-d549-4da0-8d1d-a2e3b0a9b3d8", "text": "2. Mennyi 3/4 - 1/2? (3/4 - 2/4)", "type": "multiple-choice", "options": [{"id": "81d6f4a9-2ad7-4e01-910e-9adc15eb79e9", "text": "1/4", "isCorrect": true}, {"id": "589ff4fe-fc45-4ec1-a02d-41b3cc81d32a", "text": "2/2", "isCorrect": false}, {"id": "961bdc57-1971-477d-b1f2-dedc395e1600", "text": "1/2", "isCorrect": false}, {"id": "9ae30571-6f41-4530-bc16-947670625c68", "text": "2/4", "isCorrect": false}], "timeLimit": 15}, {"id": "cf5ca556-00f0-4c9c-8543-730045ea3a9a", "text": "3. Mennyi 2/3 * 3/4?", "type": "multiple-choice", "options": [{"id": "b993af40-f016-40ba-bde9-f146974d2428", "text": "6/12 (azaz 1/2)", "isCorrect": true}, {"id": "6e5e6adc-ebdf-4f47-a217-a39b995f90c1", "text": "5/7", "isCorrect": false}, {"id": "5afcd692-0568-48b0-8e27-c236bd3e3cbc", "text": "6/7", "isCorrect": false}, {"id": "22704a89-3f65-4c73-8e08-596355a773c6", "text": "2/4", "isCorrect": false}], "timeLimit": 15}, {"id": "bf887847-9357-4274-8389-fc4d7ce6adbc", "text": "4. Mennyi 1/2 : 1/4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "b76e47c0-b193-4230-a351-ce1ee45a2d85", "text": "5. Mi a 7/8 reciproka?", "type": "multiple-choice", "options": [{"id": "2d8c47d5-24bb-40da-aae1-dfbae224a15b", "text": "8/7", "isCorrect": true}, {"id": "3bdf2bf4-43f5-4739-a2bd-14b207fb18f8", "text": "-7/8", "isCorrect": false}, {"id": "d44c6a17-34f1-4397-8154-fe1bbee28fb3", "text": "1/7", "isCorrect": false}, {"id": "80dec5db-d68c-401b-80f8-95d34f23cdee", "text": "7/8", "isCorrect": false}], "timeLimit": 15}, {"id": "6fa64b0e-3d7a-4475-ac90-8200fcacbb6d", "text": "6. Mennyi 40-nek a 3/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "b90afc03-c9d9-4845-814f-d76a834d921a", "text": "7. Egy szám és reciproka szorzata 1.", "type": "true-false", "options": [{"id": "4a79151e-c524-4d6a-b253-dfaea3986d1a", "text": "Igaz", "isCorrect": true}, {"id": "ff382e9d-5d22-4998-aead-b055430f3eb1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "fded4886-c9ca-4a88-a580-9e2a63e64f01", "text": "8. Mennyi 5 : 1/2?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "5d64b759-41a1-46cb-842e-35e8b068e144", "text": "9. A törtek szorzásakor a számlálót a számlálóval, a nevezőt a nevezővel szorozzuk.", "type": "true-false", "options": [{"id": "75d2e5ed-1a63-4a14-8db4-df9de78bca65", "text": "Igaz", "isCorrect": true}, {"id": "239e705f-4bc8-47ae-9bd5-bce3bd45f124", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "806c12fa-c2ad-476b-8d96-c2d79273ebf9", "text": "10. Hány negyedből áll 3 egész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b427114c-4b0e-44fc-bf30-34607a9ac401', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$36. óra: Matematikai játékok$q$, $q$Matematikai társasjátékok, stratégiák törtekkel, csoport- és páros munka.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Törtek$q$, $q$[{"id": "f8c1d5f1-3ab0-4e81-85a1-3dd6785f8e14", "text": "Melyik állítás igaz a matematikai társasjátékokról?", "type": "multiple-choice", "options": [{"id": "368e568c-d711-4b5a-9d22-fde5729d3c81", "text": "Fejlesztik a számolási gyorsaságot és a logikai stratégiát", "isCorrect": true}, {"id": "4736a3a6-e5e2-43a4-aee9-3b59a3eb466b", "text": "Nincs közük a matematikához", "isCorrect": false}, {"id": "d39eb6cb-9b4e-4107-b709-4006a5a203de", "text": "Kizárólag szerencse kell hozzájuk", "isCorrect": false}, {"id": "1ebda97c-9f87-4a8a-a46d-95adc5f5c05f", "text": "Tiltható az együttműködés", "isCorrect": false}], "timeLimit": 15}, {"id": "d3ee6826-230b-463f-881d-9409a9a40a5f", "text": "A tört domino játékban az egyenlő értékű törteket illesztjük össze.", "type": "true-false", "options": [{"id": "8e72cbb8-1218-4cae-a56b-4b32e510305a", "text": "Igaz", "isCorrect": true}, {"id": "dea6e249-ffec-485a-8c51-7a0837c88b10", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "056a2108-504e-4a4b-afed-7228a413e70b", "text": "Melyik tört felel meg a 0,5 tizedes törtnek?", "type": "multiple-choice", "options": [{"id": "ae9d1837-3a4f-45a5-a4a6-68634d70ceea", "text": "1/2", "isCorrect": true}, {"id": "6da02398-1f49-4045-93ed-81555b3cf657", "text": "1/5", "isCorrect": false}, {"id": "84761f88-cafc-481f-bdc7-bd5ba361c022", "text": "2/5", "isCorrect": false}, {"id": "f00deff7-6fbd-4492-93c9-097ec680c954", "text": "5/2", "isCorrect": false}], "timeLimit": 15}, {"id": "cc1816ad-8973-4d2d-b51a-9cd003f3c7be", "text": "Melyik tört felel meg a 0,25-nek?", "type": "multiple-choice", "options": [{"id": "1706d077-878f-49d0-8225-f5a33f10742c", "text": "1/4", "isCorrect": true}, {"id": "fdf10d6e-1693-4b80-a4f4-711551c38f19", "text": "1/2", "isCorrect": false}, {"id": "158252be-ba6a-406a-95a0-9a98fd8bfd64", "text": "2/5", "isCorrect": false}, {"id": "02a0e807-baf4-4469-a0bf-6d256ce79f05", "text": "3/4", "isCorrect": false}], "timeLimit": 15}, {"id": "52e14fea-f9b1-4e92-817d-ac665696900e", "text": "A 3/4 tizedes tört alakja 0,75.", "type": "true-false", "options": [{"id": "791c1697-0d6f-4c73-8c94-b645f3a1936d", "text": "Igaz", "isCorrect": true}, {"id": "4856de5e-e56d-4d9e-a85a-cc098c87a226", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f5755326-13f9-4ac1-9bb2-38a4314982ed", "text": "Mennyi 0,2 közönséges tört alakban legegyszerűbb formában?", "type": "multiple-choice", "options": [{"id": "5173e42a-1da6-4cb1-ae6b-2c286ef9bb05", "text": "1/5", "isCorrect": true}, {"id": "a975b3d1-2afa-407f-b89e-6fe388d70036", "text": "2/10", "isCorrect": false}, {"id": "e4667bb1-b416-48e6-8139-cae493287647", "text": "1/2", "isCorrect": false}, {"id": "3d607f49-d04d-4064-850c-8ee31cf40347", "text": "2/5", "isCorrect": false}], "timeLimit": 15}, {"id": "098d4c69-cff0-490b-a434-bb9245e0db68", "text": "A tört-bingó játékban a válaszok gyors és pontos kiszámítása a nyerő stratégia.", "type": "true-false", "options": [{"id": "0948a7e2-4bf7-47b3-a555-9f745f2e3d97", "text": "Igaz", "isCorrect": true}, {"id": "2ee99956-7a74-4245-98e1-5e4d4ce68c67", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('50e2e978-dd79-4784-81a1-05c376e920d1', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$37. óra: Mit tanultunk a tizedes törtekről?$q$, $q$Tizedes törtek helyi értékei, összeadása és kivonása.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Törtek$q$, $q$[{"id": "a140a512-5cb8-4353-a1f5-3487f89c7bc9", "text": "Mi a tizedesvessző utáni első helyi érték neve?", "type": "multiple-choice", "options": [{"id": "fd1bb4c0-e328-4f55-ba07-7c07d5bbb386", "text": "Tizedek", "isCorrect": true}, {"id": "765e7bb9-bab5-45d1-83ee-41967a316aa6", "text": "Századok", "isCorrect": false}, {"id": "fe288b67-0b4a-4fc2-9c55-cbbe11d18499", "text": "Ezredeket", "isCorrect": false}, {"id": "9b27c498-eb7f-4456-a0a7-755afabae2c9", "text": "Egyesek", "isCorrect": false}], "timeLimit": 15}, {"id": "aa4e32c4-7e3b-4537-a63a-ff7a456d4ec7", "text": "Mi a tizedesvessző utáni második helyi érték neve?", "type": "multiple-choice", "options": [{"id": "a84811c4-deea-4381-8e93-3380aaa67946", "text": "Századok", "isCorrect": true}, {"id": "02db7c99-4116-450c-ac98-f74d5accb09c", "text": "Tizedek", "isCorrect": false}, {"id": "b6f15f6b-839b-4444-b182-6fc6bed493ce", "text": "Ezredek", "isCorrect": false}, {"id": "2d8ac2bb-2f6c-4394-ba20-2fdbdd1b5d91", "text": "Tízesek", "isCorrect": false}], "timeLimit": 15}, {"id": "8858a590-0ea8-4625-99f1-9870fff70f7c", "text": "Mennyi 3,45 + 2,13?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5.58"}, {"id": "c7aa790a-930a-4ab3-8071-593dfdaebe01", "text": "Mennyi 7,8 - 3,5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4.3"}, {"id": "0b37cfef-8fe2-4b44-a3b7-12618355402c", "text": "Tizedes törtek írásbeli összeadásakor a tizedesvesszőknek egymás alá kell kerülniük.", "type": "true-false", "options": [{"id": "0df8fedf-4409-45bd-b069-5546b58e6708", "text": "Igaz", "isCorrect": true}, {"id": "6f7f2e59-ccaf-49a3-aa94-50b6cde08d12", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1ede968c-25ce-418d-9307-0633e37c2e5d", "text": "Mennyi 5,6 + 4,4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "4f4589c6-33bd-48ef-acf9-bc51871dffa8", "text": "Melyik szám nagyobb: 4,05 vagy 4,5?", "type": "multiple-choice", "options": [{"id": "f9ced1d2-3bc4-4a67-87e9-85378402cb7a", "text": "4,5 (mert 4,5 = 4,50)", "isCorrect": true}, {"id": "9597a4d9-33d1-49f0-8366-2176c99d42d7", "text": "4,05", "isCorrect": false}, {"id": "639485ba-2a54-47d3-ac04-681efc98a92f", "text": "Egyenlőek", "isCorrect": false}, {"id": "490ce7db-ee48-4965-9e76-39e5da607b3d", "text": "Nem eldönthető", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('18612cd5-dc7d-49ae-8a7a-559055ec6566', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$38. óra: Szorzás tizedes törttel$q$, $q$Tizedes tört szorzása egész számmal és tizedes törttel, vesszőhely meghatározása.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Törtek$q$, $q$[{"id": "8a716b64-b823-418c-8844-bd7cfa90915d", "text": "Hogyan határozzuk meg a tizedesjegyek számát két tizedes tört szorzatában?", "type": "multiple-choice", "options": [{"id": "6d157e95-01b6-4fcf-ac49-2320bc4a4f9b", "text": "A tényezők tizedesjegyeinek számát összeadjuk", "isCorrect": true}, {"id": "8e4bf91f-5db8-42ba-8f1c-3c2bf76d594a", "text": "A nagyobbik tényező tizedesjegyeit vesszük", "isCorrect": false}, {"id": "319aba91-b911-4442-845b-260cfc9ade4e", "text": "Mindig 1 tizedesjegy lesz", "isCorrect": false}, {"id": "9c221a8d-a11e-494d-a40f-5114344a2e9b", "text": "Nem lesz tizedesjegy", "isCorrect": false}], "timeLimit": 15}, {"id": "0fa3e35a-74b3-4861-9efa-764e009c2fd4", "text": "Mennyi 0,3 * 0,2? (3*2 = 6, 2 tizedesjegy)", "type": "multiple-choice", "options": [{"id": "beb3b1ed-2ce1-4519-a34d-98cd297fd217", "text": "0,06", "isCorrect": true}, {"id": "2069e2e2-afc2-4502-9ffa-494ffbd00479", "text": "0,6", "isCorrect": false}, {"id": "a59b41e9-cddb-4287-82bc-13a08dc84739", "text": "6,0", "isCorrect": false}, {"id": "96759872-6950-43df-b99d-3754951a8580", "text": "0,006", "isCorrect": false}], "timeLimit": 15}, {"id": "b615fdce-324e-44c7-8bad-ee4721fd5382", "text": "Mennyi 2,5 * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "d2e43846-ad43-42c8-b229-2823922ccdd5", "text": "Mennyi 1,2 * 0,5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0.6"}, {"id": "66c08dee-b17c-4bbb-8af3-1054df076b61", "text": "Ha egy tizedes törtet 10-zel szorzunk, a tizedesvessző egy hellyel jobbra lép.", "type": "true-false", "options": [{"id": "f16748d2-fe0f-4db7-856e-09f476370bb9", "text": "Igaz", "isCorrect": true}, {"id": "32137235-665f-4726-b2aa-a5e3b097d72e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9aff3d95-ce7f-4f65-ab3a-b0167ed208e2", "text": "Mennyi 3,45 * 100?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "345"}, {"id": "2742dc15-973a-401b-8fc9-7311b484c7a7", "text": "Mennyi 0,1 * 0,1?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0.01"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('59e63653-3fcd-4e91-8d6e-c76d31aed546', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$39. óra: Osztás tizedes törttel$q$, $q$Tizedes törttel való osztás szabálya, osztó egész számmá alakítása (bővítés 10-zel, 100-zal).$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Törtek$q$, $q$[{"id": "27848b4b-cc92-4a9b-b083-26470c934996", "text": "Mit teszünk tizedes törttel való osztáskor először?", "type": "multiple-choice", "options": [{"id": "1cf09a1d-d613-4c18-a2cf-40ce2002b1fb", "text": "Az osztandót és az osztót is megszorozzuk 10-zel/100-zal, hogy az osztó egész szám legyen", "isCorrect": true}, {"id": "5295b3f1-10bf-4e19-980e-d8ab98dcaf18", "text": "Elhagyjuk a tizedesvesszőt az osztandóból", "isCorrect": false}, {"id": "96931fe1-5b46-440d-8589-c03d82dfba03", "text": "Kivonjuk az osztót az osztandóból", "isCorrect": false}, {"id": "705067c2-5736-47cf-b5c2-922b59a603e8", "text": "Csak az osztót szorozzuk meg", "isCorrect": false}], "timeLimit": 15}, {"id": "45afc706-cb94-43bc-bcac-a1c82b748e26", "text": "Mennyi 2,4 : 0,6? (24 : 6)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "b584011c-c872-4b9f-9f33-c80e4332d632", "text": "Mennyi 1,5 : 0,3? (15 : 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "defd1042-0d27-46dc-93fc-44d8343319ec", "text": "Ha egy tizedes törtet 10-zel osztunk, a tizedesvessző 1 hellyel balra lép.", "type": "true-false", "options": [{"id": "ef929de8-c6ef-41b5-8821-05a1d4744cb8", "text": "Igaz", "isCorrect": true}, {"id": "56ea77c6-ca6b-449c-bc38-0135e50527a8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1ae10058-ff89-450d-b1be-51ea7bf9f581", "text": "Mennyi 45,6 : 10?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4.56"}, {"id": "67ed1dc9-4aa5-4668-a063-8c3021cb1448", "text": "Mennyi 3,6 : 0,1? (36 : 1)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "26f0b547-1f45-4597-bae6-f2511a666808", "text": "A tizedes törttel való osztást ellenőrizhetjük szorzással.", "type": "true-false", "options": [{"id": "b00e1913-3fa2-433b-9627-fba3a656d072", "text": "Igaz", "isCorrect": true}, {"id": "50559b2a-76b7-4b6a-93c5-93887d5d594b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('beac8656-8340-4228-97f2-49e2f1150ddb', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$40. óra: Hétköznapi problémák megoldása tizedes törtek szorzásának, osztásának felhasználásával$q$, $q$Vásárlási, mértékegységes és szöveges feladatok.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Törtek$q$, $q$[{"id": "c03ce1f8-f9a7-4026-878f-ddca01ee3500", "text": "1 kg sajt ára 3200 Ft. Mennyibe kerül 0,5 kg sajt? (3200 * 0,5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1600"}, {"id": "d25acac4-49ef-4fe9-a3f5-b744b6b61206", "text": "Peti 3,5 kg almát vett 400 Ft/kg áron. Hány Ft-ot fizetett?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1400"}, {"id": "451f6f79-746f-4b96-9669-1e5ff920e077", "text": "Egy 4,8 méteres lécet 4 egyenlő darabra vágunk. Hány méter egy darab?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1.2"}, {"id": "553e56a7-8a42-4d7a-aef7-2dbc7e87a69e", "text": "Ha 0,25 liter üdítő 150 Ft, akkor 1 liter üdítő (4 * 0,25) 600 Ft-ba kerül.", "type": "true-false", "options": [{"id": "05b9cb3b-1260-451b-88d4-e117d3a32cba", "text": "Igaz", "isCorrect": true}, {"id": "9340ed88-6256-4fc3-ba46-c54e33e96bd2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9695272e-58c3-431e-ad32-005da81c47cf", "text": "Hány liter benzin fér a tankba 12000 Ft-ért, ha 1 liter benzin 600 Ft?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "10ff0ea5-27a5-411c-9bb1-d1f0d5811f01", "text": "A becslés segít ellenőrizni, hogy a tizedesvesszőt jó helyre tettük-e a végeredményben.", "type": "true-false", "options": [{"id": "46eda894-6d60-45ed-b149-b01cc9622bb9", "text": "Igaz", "isCorrect": true}, {"id": "ebac77a3-96a3-4aba-80cc-681cb655b102", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9e3a2e58-3186-4581-9f99-ce7156c14be4", "text": "Mennyi 1,5 kg narancs ára, ha 1 kg 800 Ft?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1200"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;